import { writeFile } from "fs/promises";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

const __dirname = dirname(fileURLToPath(import.meta.url));
export const TOKENS_PATH = join(__dirname, "../../../styles/tokens.css");

/**
 * Numbers in scale order, then names alphabetically, so moving a layer in Figma
 * doesn't reorder the generated file.
 */
function ordered(group) {
  const entries = Object.entries(group);
  const isNumber = ([k]) => /^[\d.]+$/.test(k);
  return [
    ...entries.filter(isNumber).sort(([a], [b]) => Number(a) - Number(b)),
    ...entries
      .filter((e) => !isNumber(e))
      .sort(([a], [b]) => a.localeCompare(b)),
  ];
}

/** Tailwind reads `--spacing-0_5` for the `0.5` scale key. */
const key = (name) => name.replace(/\./g, "_");

function lines(prefix, group) {
  return ordered(group).map(([name, value]) =>
    name === "DEFAULT"
      ? `  --${prefix}: ${value};`
      : `  --${prefix}-${key(name)}: ${value};`,
  );
}

/** Renders a token set as a Tailwind v4 @theme block. Deterministic. */
export function render(tokens, { source }) {
  const text = ordered(tokens.text).flatMap(([name, { size, lineHeight }]) => [
    `  --text-${name}: ${size};`,
    `  --text-${name}--line-height: ${lineHeight};`,
  ]);
  const sections = [
    ["Spacing", lines("spacing", tokens.spacing)],
    ["Containers", lines("container", tokens.container)],
    ["Radius", lines("radius", tokens.radius)],
    ["Shadow", lines("shadow", tokens.shadow)],
    ["Type size and its default line height", text],
    ["Font weight", lines("font-weight", tokens["font-weight"])],
    ["Line height", lines("leading", tokens.leading)],
    ["Letter spacing", lines("tracking", tokens.tracking)],
  ];
  const body = sections
    .map(([title, rows]) => [`  /* ${title} */`, ...rows].join("\n"))
    .join("\n\n");
  return `/** @format */
/**
 * @fileoverview Design tokens generated by the Figma sync. Do not edit by hand;
 * change the layer on the Figma "Tokens" page and run npm run build:design.
 * @source ${source}
 */

@theme {
${body}
}
`;
}

export async function write(tokens, meta) {
  await writeFile(TOKENS_PATH, render(tokens, meta), "utf8");
}
